INSERT INTO constant (name, value, meaning) VALUES ('K', 1, 'A page starts as one neutral vote (0.5) with this weight. Truth = (positive + k x 0.5) / (positive + negative + k). With k = 1 an unargued page reads 0.5, a page with one unrebutted reason moves part of the way, not all the way, to certainty.');
INSERT INTO constant (name, value, meaning) VALUES ('UNARG', 0.5, 'What a row reads for Truth when it has no page yet: a coin flip. Give it a page and the page decides.');
INSERT INTO constant (name, value, meaning) VALUES ('DEFLINK', 1, 'A reason placed under a conclusion is presumed relevant until a linkage page says otherwise; the burden is on the challenger. Open the linkage page ("If it were true that X, it would necessarily strengthen Y") and argue it down. The scorecard counts how many rows still rest on this presumption.');
INSERT INTO constant (name, value, meaning) VALUES ('DEFIMP', 0.5, 'The neutral start for importance, the wiki''s own rule: an importance nobody has argued opens at 0.5, neither trivial nor decisive, until an importance page names the issues the row addresses and their argued importance takes over. Not a penalty; the absence of a claim either way.');
INSERT INTO constant (name, value, meaning) VALUES ('DEFUNIQ', 1, 'A reason is presumed distinct until a uniqueness page shows the overlap.');
INSERT INTO page (id, kind, text, topic, bottom_line, positivity, logical_form) VALUES (1, 'belief', 'Ending single-family-only zoning lowers housing costs in the cities that do it.', 'Housing', 'The agree side leads on evidence from Auckland, Minneapolis and the spillover studies; the honest con is that upzoning without cheaper construction produces little where land is dearest.', 55, '(Zoning is the binding constraint on supply in high-cost cities) AND (more supply lowers prices). The normative component (lower prices are the right goal) is separable.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (2, 'claim', 'Where cities have allowed more homes per lot, permits rose and rents grew more slowly than in comparable cities that did not.', 'Housing', 1, 'Three cities point the same way; the open question is how much of each divergence the single-family change itself explains.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (3, 'claim', 'Housing prices track the gap between demand and the number of homes; zoning that caps homes per lot is the binding constraint on supply in high-cost metros.', 'Housing', 1, 'The premium evidence is strong for coastal metros; construction cost is a serious rival explanation in the 2020s.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (4, 'claim', 'New market-rate homes lower rents in nearby existing buildings by pulling higher-income renters out of older housing.', 'Housing', 1, 'The replicated finding is a small local rent decrease; the contested part is what happens to the very cheapest nearby buildings.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (5, 'claim', 'Allowing duplexes and small apartments on single-family lots adds homes without public subsidy, so it is the cheapest affordability tool available.', 'Housing', 1, 'True on public cost per unit; the disagree side is right that it is a slow tool for the poorest renters.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (6, 'claim', 'Upzoning alone produces few homes where land is expensive and construction costs are high; California''s 2021 lot-split law produced only a few hundred units in its first two years.', 'Housing', 1, 'Right about SB 9 and about the cost environment; weaker as a general claim, since better-designed reforms are producing rising counts.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (7, 'claim', 'Allowing more units raises land values, which can raise the price of existing homes and displace lower-income owners and renters through redevelopment.', 'Housing', 1, 'The land-value effect is real; the displacement claim runs against the better evidence.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (8, 'claim', 'Neighborhood character, parking, school crowding and infrastructure capacity are real costs that fall on existing residents while the benefits go to newcomers.', 'Housing', 1, 'Some costs are real and mostly unpriced; whether they bear on housing costs is decided on the linkage page (tab 14).');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (9, 'claim', 'Rents in Minneapolis and Austin also fell because of a building boom financed by cheap money in 2021-2022, which is not repeatable.', 'Housing', 1, 'Right about Austin''s timing, weak on Minneapolis; the two causes are not exclusive.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (10, 'claim', 'Minneapolis rents grew far more slowly than the rest of Minnesota from 2017 to 2023 because of its 2019 zoning and parking reforms.', 'Housing', 2, 'The divergence is real; how much of it the single-family change explains is open, and the 2017 start is the strongest objection.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (11, 'importance', 'Housing', 1, 4, 1, 'reason to agree', 'Renters in existing buildings, whose rents the new homes pull down.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, bridge, bottom_line) VALUES (12, 'uniqueness', 'Housing', 1, 5, 3, 'X adds a comparison of public cost per home against subsidy programs; Z says nothing about what the reform costs the public.', 'The cost comparison is new, the mechanism is shared.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (13, 'claim', 'Upzoning along Chicago transit corridors in 2013 and 2015 raised land values and prices without increasing construction, which shows upzoning can raise housing costs.', 'Housing', 7, 'A solid finding about small corridor upzonings; it says little about citywide reform.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (14, 'linkage', 'Housing', 1, 8, 1, 'Argument', 'Weakens', 'Costs to existing residents would weaken the belief only if they raised housing costs or got the reform repealed; on their own they are a separate cost.', 'Low linkage: a true argument aimed at a different question. It counts fully in the cost-benefit table.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (15, 'importance', 'Housing', 1, 8, 1, 'reason to disagree', 'Existing residents, who bear the parking, school and infrastructure costs.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (16, 'interest', 'Some homeowners want to keep lower-income households out of their neighborhood.', 'Housing', 1, 1, 'Status', 'Income mix of new residents in reformed neighborhoods against the existing residents', 'Lower-income households move in as costs fall', 'Income mix unchanged', 'Not yet measured for reformed single-family neighborhoods', 'Held by some, valid by almost no standard; kept on the page so the scoring is visible.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (17, 'linkage', 'Housing', 1, 56, 1, 'Media', 'Supports', 'The work measures the price of permission; the belief is about removing one kind of permission.', 'Bearing: does the work speak to this belief at all?');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (18, 'claim', 'Ending single-family-only zoning leaves rents in reform cities about 5 percent below the counterfactual after five years.', 'Housing', 1, 'Plausible where building follows; the magnitude is an estimate, not a measurement.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (19, 'claim', 'Ending single-family-only zoning adds about 3 homes per 1,000 residents per year without public subsidy.', 'Housing', 1, 'Auckland-scale reforms reach the number; timid ones do not.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (20, 'claim', 'Infill housing from zoning reform cuts vehicle miles per new resident by about 20 percent compared with the same growth at the urban edge.', 'Housing', 1, 'Well supported for the residents who would otherwise live at the edge; the counterfactual is the soft spot.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (21, 'claim', 'Ending single-family-only zoning reduces the value of existing single-family homes by about 3 percent where new homes compete with them.', 'Housing', 1, 'Runs against the evidence: upzoning has raised, not lowered, existing values in the cases studied.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (22, 'claim', 'Redevelopment under zoning reform displaces about 50 households per 1,000 new units built.', 'Housing', 1, 'Direct demolition displacement is real but small for middle housing; the net effect may be negative.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (23, 'claim', 'Each new unit from zoning reform imposes about 20,000 dollars of school, parking and utility costs on built-out neighborhoods.', 'Housing', 1, 'Some cost is real; the figure is high against what cost-of-service studies show.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (24, 'interest', 'Renters and first-time buyers need housing prices they can afford.', 'Housing', 1, 1, 'Opportunity', 'Share of renters paying more than 30 percent of income on housing, reform cities against matched cities', 'Falls in reform cities against matched cities', 'No difference from matched cities', 'About half of renters nationally (Census ACS); not yet compared for reform cities', 'Near the top of any hierarchy of needs; validity is not seriously contested.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (25, 'interest', 'Current homeowners need to protect the value of their homes.', 'Housing', 1, 1, 'Security', 'Resale price of existing single-family homes near new multiplexes, against comparable homes with no new neighbors', 'Slightly lower where new homes compete', 'Unchanged or higher', 'Mixed: land value up on upzoned lots, resale effects on neighbors small so far (Freemark 2020; Sightline 2023)', 'Valid as security, weaker as a claim to control what neighbors build.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (26, 'claim', 'Allowing up to four units on every residential lot by right, with design standards and no parking minimums, with infrastructure funded from the added tax base, would satisfy the main interests of both sides.', 'Housing', 1, 'The most-adopted middle ground; parking is where it succeeds or fails.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (27, 'claim', 'More housing supply lowers prices and rents relative to the counterfactual.', 'Housing', 1, 'The basic economics holds up; induced demand slows the effect without erasing it.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (28, 'claim', 'Lower housing costs are the right goal even where current owners lose value.', 'Housing', 1, 'A values ranking, not a fact; the page scores the arguments for each ranking.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (29, 'claim', 'Builders respond to permission with construction at prices below current rents.', 'Housing', 1, 'True in most reform cities; false so far in California''s narrow reform.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (30, 'claim', 'New supply mainly serves higher-income newcomers rather than filtering down.', 'Housing', 1, 'True about first occupants, false about where the vacancy chain ends.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (31, 'claim', 'Supporters'' advertised reason (more homes, lower rents) differs from their actual driver (developer returns).', 'Housing', 1, 'Partly true for some funders, not for the movement.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (32, 'claim', 'Opponents'' advertised reason (neighborhood character) differs from their actual driver (home equity and exclusion).', 'Housing', 1, 'Well supported as a tendency; not true of every opponent.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (33, 'claim', 'The benefits of zoning reform arrive years after the political fight, which makes the reform hard to sustain.', 'Housing', 1, 'A real obstacle: the costs are immediate and the benefits are slow.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (34, 'claim', 'Opponents cannot point to a high-cost city that fixed affordability without adding supply, which weakens their position.', 'Housing', 1, 'Holds, with Vienna as the exception that added supply by other means.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (35, 'claim', 'Abolishing zoning entirely would lower housing costs.', 'Housing', 1, 'The more extreme cousin of the belief; it inherits the supply evidence and adds costs the parent does not.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (36, 'claim', 'Ending single-family-only zoning slows rent growth modestly in high-demand cities and changes little elsewhere.', 'Housing', 1, 'The version of the belief most of the evidence supports directly.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (37, 'claim', 'After Auckland upzoned about three quarters of its residential land in 2016, dwelling consents in upzoned areas rose sharply relative to trend, adding an estimated 20,000-plus homes in five years.', 'Housing', 1, 'A peer-reviewed finding with a clear design; the completions caveat is the main open point.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (38, 'claim', 'Austin permitted more apartments per resident than any large U.S. metro in 2021-2023, and asking rents fell more than 15 percent from their 2023 peak by 2025.', 'Housing', 1, 'The permit ranking and the rent decline are both well documented; the size of the sitting-tenant effect is not.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (39, 'claim', 'New apartment buildings in New York, San Francisco and Helsinki lowered rents in buildings within a few hundred meters by 1 to 6 percent relative to controls.', 'Housing', 1, 'Replicated across cities; the lowest-rent tier is the contested corner.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (40, 'claim', 'A UC Berkeley Terner Center review found fewer than 500 SB 9 applications statewide in the law''s first year, concentrated in a handful of cities.', 'Housing', 1, 'Well documented; the number is low by any count.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (41, 'linkage', 'Housing', 1, 57, 1, 'Media', 'Supports', 'The work describes the belief''s outcome in the best-known reform city.', 'Bearing: does the work speak to this belief at all?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (42, 'linkage', 'Housing', 1, 58, 1, 'Media', 'Weakens', 'The work is the belief''s outcome reversed, in a setting that may not compare.', 'Bearing: does the work speak to this belief at all?');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (43, 'claim', 'Land values rise on upzoned lots before construction starts.', 'Housing', 1, 'Well established.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (44, 'claim', 'Permit applications rise within a year of reform where the rules are simple.', 'Housing', 1, 'True conditional on simple rules.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (45, 'claim', 'Rents settle below the counterfactual as supply accumulates over a decade.', 'Housing', 1, 'The central long-run prediction; the data will arrive around 2030.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (46, 'claim', 'Neighborhoods gain small apartment buildings and lose some detached homes over a decade.', 'Housing', 1, 'Directionally certain, small in magnitude.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (47, 'interest', 'Builders need permission to build what the market will buy.', 'Housing', 1, 1, 'Free enterprise', 'Homes permitted per 1,000 residents per year in reform cities against matched cities', 'Rises after reform', 'No difference from matched cities', 'Auckland: consents roughly doubled in upzoned areas, 2016-2021 (Greenaway-McGrevy and Phillips 2023)', 'Valid as an economic interest; weaker as a claim on policy priority.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (48, 'interest', 'Residents of older neighborhoods need protection from displacement by redevelopment.', 'Housing', 1, 1, 'Stability', 'Households moving out within 500 meters of redevelopment, per 1,000 new units, against control blocks', 'No higher than controls as rents ease', 'Higher than controls', 'Lower near new construction in San Francisco (Pennington 2021); not measured for middle housing', 'A valid need whose size is contested.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (49, 'claim', 'Both sides want their children able to afford to live in the city they grew up in.', 'Housing', 1, 'About as shared as interests get.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (50, 'claim', 'Supply optimism (assuming permission alone produces homes) biases supporters of zoning reform.', 'Housing', 1, 'Real, and easy to see in California.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (51, 'claim', 'Status-quo bias and loss aversion about home values bias opponents of zoning reform.', 'Housing', 1, 'Well supported as a tendency.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (52, 'claim', 'Cities that reformed in 2019-2023 will show slower rent growth than matched cities through 2030.', 'Housing', 1, 'The central pending test of the belief.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (53, 'claim', 'Reform and non-reform cities will show the same rent trajectories once interest rates and migration are controlled for.', 'Housing', 1, 'The rival''s prediction; the controlled comparison will decide it.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (54, 'claim', 'Minneapolis rents will grow more slowly than the Minnesota average in the five years after the 2019 reform.', 'Housing', 1, 'Confirmed as stated; attribution remains partly open.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (55, 'claim', 'California''s SB 9 lot splits will add thousands of homes within two years of taking effect.', 'Housing', 1, 'Disconfirmed; the failed prediction counts against the belief.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, type, where_found, bridge, bottom_line) VALUES (56, 'media', 'Glaeser and Gyourko, The Economic Implications of Housing Supply (2018)', 'Housing', 1, 1, 'Study', 'Journal of Economic Perspectives 32(1), 3-30', 'Zoning and other rules keep prices far above construction cost in coastal metros.', 'Foundational for the supply argument.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, type, where_found, bridge, bottom_line) VALUES (57, 'media', 'Pew Charitable Trusts, Minneapolis housing analysis (2024)', 'Housing', 1, 1, 'Article', 'pewtrusts.org, housing policy initiative, 2024', 'Minneapolis rents lagged the state after 2019 while its housing stock grew faster.', 'The best-known case, descriptively strong, causally open.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, type, where_found, bridge, bottom_line) VALUES (58, 'media', 'Freemark, Upzoning Chicago (2020)', 'Housing', 1, 1, 'Study', 'Urban Affairs Review 56(3), 758-789', 'Small corridor upzonings raised land prices without adding construction within five years.', 'A real caution about small upzonings.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (59, 'claim', 'Minneapolis 2040 (2019), Oregon HB 2001 (2019) and California SB 9 (2021) and SB 79 (2025) assume that ending single-family-only zoning lowers housing costs.', 'Housing', 1, 'Institutional agreement, documented; not proof.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (60, 'claim', 'Local zoning authority under state enabling acts and environmental review statutes complicate the belief that ending single-family-only zoning lowers housing costs.', 'Housing', 1, 'The legal machinery cuts both ways and is moving.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (61, 'claim', 'Prices fall when supply is allowed to meet demand.', 'Housing', 1, 'The upstream principle the belief inherits from.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (62, 'claim', 'Local communities should control what gets built near them.', 'Housing', 1, 'A values claim; the outcomes evidence leans against it.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (63, 'claim', 'Parking minimums should be abolished near transit.', 'Housing', 1, 'A downstream belief that inherits most of this page''s logic.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (64, 'claim', 'Historic districts should be exempt from upzoning.', 'Housing', 1, 'Defensible for buildings, abused for neighborhoods.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (65, 'claim', 'Edward Glaeser is on record that regulation, including zoning, raises housing prices.', 'Housing', 1, 'Documented.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (66, 'claim', 'The Pew Charitable Trusts housing policy initiative is on record that zoning reform lowers housing costs.', 'Housing', 1, 'Documented.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (67, 'claim', 'Livable California is on record opposing SB 9 and SB 50.', 'Housing', 1, 'Documented.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (68, 'claim', 'Yonah Freemark is on record that upzoning can raise prices without adding housing.', 'Housing', 1, 'On record for the narrow finding, not against reform in general.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (69, 'claim', 'A multi-city study shows rents falling relative to matched controls after zoning reform, with the effect growing over time.', 'Housing', 1, 'Pending: the study that would settle the belief has not been done.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (70, 'claim', 'Reform cities'' price-to-construction-cost premium shrinks in the years after reform.', 'Housing', 1, 'Pending, and ambiguous unless construction costs are held constant.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (71, 'claim', 'Reform cities'' rents tracked non-reform cities once the 2021-2022 construction boom is controlled for.', 'Housing', 1, 'Pending; the Austin and Minneapolis cases pull in opposite directions.');
INSERT INTO page (id, kind, text, topic, parent_id, bottom_line) VALUES (72, 'claim', 'Upzoned single-family lots were redeveloped mainly into larger single homes rather than into more units.', 'Housing', 1, 'Pending; early permit data lean against it.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (73, 'interest', 'Newcomers and young families need somewhere to live in the city.', 'Housing', 1, 1, 'Opportunity', 'Homes added per 1,000 residents per year and the rental vacancy rate, reform cities against matched cities', 'Homes added rise and vacancy loosens', 'No difference from matched cities', 'Minneapolis added housing faster than the rest of Minnesota, 2017-2023 (Pew 2024)', 'As basic as needs get; contested only on who gets a say.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (74, 'interest', 'Commuters and the climate need homes near jobs rather than at the urban edge.', 'Housing', 1, 1, 'Sustainability', 'Vehicle miles per new resident, infill homes against homes at the urban edge', 'Lower for infill', 'No difference', 'Infill households drive less than edge households in every study cited on the benefit page; the margin varies', 'Real and diffuse; it rarely drives anyone to a hearing.');
INSERT INTO page (id, kind, text, topic, parent_id, y_id, value, measured_by, if_true, if_false, latest, bottom_line) VALUES (75, 'interest', 'Existing residents need to keep the neighborhood character, parking and school capacity they have.', 'Housing', 1, 1, 'Community', 'Street parking occupancy and school enrollment against capacity in reformed neighborhoods', 'Within capacity, funded by the added tax base', 'Over capacity, with infrastructure bills following', 'Mixed; few systematic measurements', 'Real costs, mostly unpriced; weaker as a claim on others'' lots.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (76, 'importance', 'Housing', 1, 2, 1, 'reason to agree', 'Renters, whose rents grew more slowly, and builders, who got permits.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (77, 'importance', 'Housing', 1, 3, 1, 'reason to agree', 'Everyone priced out by the gap between demand and the number of homes: renters and newcomers.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (78, 'importance', 'Housing', 1, 5, 1, 'reason to agree', 'Renters and newcomers, who get homes without a subsidy anyone has to fund.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (79, 'importance', 'Housing', 1, 6, 1, 'reason to disagree', 'Renters and newcomers, who get no relief if the reformed lots produce few homes.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (80, 'importance', 'Housing', 1, 7, 1, 'reason to disagree', 'Owners whose land values change and residents who could be displaced by redevelopment.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (81, 'importance', 'Housing', 1, 9, 1, 'reason to disagree', 'Renters, whose relief would not repeat if cheap money rather than zoning produced it.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (82, 'importance', 'Housing', 1, 37, 1, 'supporting finding', 'Builders, who got consents, and renters, if the consents became homes.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (83, 'importance', 'Housing', 1, 10, 1, 'supporting finding', 'Minneapolis renters, whose rents lagged the state.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (84, 'importance', 'Housing', 1, 38, 1, 'supporting finding', 'Austin renters, whose asking rents fell after the permitting boom.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (85, 'importance', 'Housing', 1, 39, 1, 'supporting finding', 'Renters in buildings near new construction.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (86, 'importance', 'Housing', 1, 40, 1, 'weakening finding', 'Newcomers and renters, who got almost no homes from California''s lot-split law.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (87, 'importance', 'Housing', 1, 13, 1, 'weakening finding', 'Owners of upzoned parcels, whose land rose in value, and renters, who got no homes.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (88, 'importance', 'Housing', 1, 52, 1, 'prediction if the belief is true', 'Renters in reform cities through 2030.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (89, 'importance', 'Housing', 1, 54, 1, 'prediction if the belief is true', 'Minneapolis renters against the state average.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (90, 'importance', 'Housing', 1, 55, 1, 'prediction if the belief is true', 'Newcomers who would live in homes from California lot splits.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (91, 'importance', 'Housing', 1, 69, 1, 'prediction if the belief is true', 'Renters across many reform cities, over time.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (92, 'importance', 'Housing', 1, 70, 1, 'prediction if the belief is true', 'Buyers priced out by the gap between home prices and construction cost.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (93, 'importance', 'Housing', 1, 53, 1, 'prediction if the belief is false', 'Renters, if reform cities turn out no different from others.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (94, 'importance', 'Housing', 1, 71, 1, 'prediction if the belief is false', 'Renters, if the 2021-2022 boom explains the whole effect.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, rowkind, bridge) VALUES (95, 'importance', 'Housing', 1, 72, 1, 'prediction if the belief is false', 'Newcomers, if redeveloped lots added no homes.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (96, 'linkage', 'Housing', 1, 2, 47, 'Interest', 'Supports', 'The reason mentions permits as the path to slower rents; whether it is about builders or only about renters is the question.', 'Bearing: how far the row is really about this interest.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (97, 'linkage', 'Housing', 1, 7, 48, 'Interest', 'Supports', 'Land values and displacement are related but not the same harm.', 'Bearing: how far the row is really about this interest.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (98, 'linkage', 'Housing', 1, 2, 1, 'Argument', 'Supports', 'Slower rent growth after reform, against matched cities, is the outcome the belief predicts, so the reason supports the belief to the extent the matching holds.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (99, 'linkage', 'Housing', 1, 3, 1, 'Argument', 'Supports', 'If zoning binds supply, ending single-family-only zoning relaxes the constraint and prices should fall by however much the constraint bound.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (100, 'linkage', 'Housing', 1, 4, 1, 'Argument', 'Supports', 'If each new building lowers nearby rents, a reform that produces many buildings lowers rents across the city.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (101, 'linkage', 'Housing', 1, 5, 1, 'Argument', 'Supports', 'A tool that adds homes cheaply is more likely to be used at scale, and homes added at scale lower costs.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (102, 'linkage', 'Housing', 1, 6, 1, 'Argument', 'Weakens', 'If upzoning produces few homes where land is dear, there is no supply to lower costs there.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (103, 'linkage', 'Housing', 1, 7, 1, 'Argument', 'Weakens', 'If upzoning raises land values and displaces residents, housing costs rise for some people even if average rents fall.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (104, 'linkage', 'Housing', 1, 9, 1, 'Argument', 'Weakens', 'If cheap money caused the building boom, the rent declines in reform cities do not show that zoning did.', 'Linkage: does the reason bear on the belief at all, if it is true?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (105, 'linkage', 'Housing', 1, 37, 1, 'Evidence', 'Supports', 'More consents in upzoned areas is the first link of the chain from permission to lower costs.', 'Linkage: does the finding bear on the belief, if it is accurate?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (106, 'linkage', 'Housing', 1, 10, 1, 'Evidence', 'Supports', 'A reform city whose rents lag its state after reform is what the belief predicts.', 'Linkage: does the finding bear on the belief, if it is accurate?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (107, 'linkage', 'Housing', 1, 38, 1, 'Evidence', 'Supports', 'Permits led rents down in Austin, which is the chain the belief describes.', 'Linkage: does the finding bear on the belief, if it is accurate?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (108, 'linkage', 'Housing', 1, 39, 1, 'Evidence', 'Supports', 'New buildings lowering nearby rents is how reform reaches existing tenants.', 'Linkage: does the finding bear on the belief, if it is accurate?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (109, 'linkage', 'Housing', 1, 40, 1, 'Evidence', 'Weakens', 'If a reform adds almost no homes, it cannot lower costs through supply.', 'Linkage: does the finding bear on the belief, if it is accurate?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (110, 'linkage', 'Housing', 1, 13, 1, 'Evidence', 'Weakens', 'Upzoning that raised prices without adding homes is the belief''s outcome reversed, if the setting is comparable.', 'Linkage: does the finding bear on the belief, if it is accurate?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, type, direction, bridge, bottom_line) VALUES (111, 'linkage', 'Housing', 1, 52, 1, 'Prediction', 'Supports', 'Would this observation tell the two sides apart, or do both expect it?', 'Diagnosticity: a result both sides expect scores low here.');
