INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (119, 'driver', 'Housing', 1, 24, 1, 'Support', 'Support that tracked land ownership rather than rent burden would point to a different driver.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (120, 'driver', 'Housing', 1, 47, 1, 'Support', 'A coalition that kept its size and intensity with builder money removed would show builders are not the driver.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (121, 'driver', 'Housing', 1, 73, 1, 'Support', 'Support that tracked age and tenure rather than housing status would point elsewhere.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (122, 'driver', 'Housing', 1, 74, 1, 'Support', 'Turnout that tracked commute length would show this interest driving support; it does not so far.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (123, 'driver', 'Housing', 1, 25, 1, 'Opposition', 'Opposition as strong among renters as among owners would point to attachment rather than equity.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (124, 'driver', 'Housing', 1, 48, 1, 'Opposition', 'Opposition concentrated where displacement risk is lowest would show another driver at work.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (125, 'driver', 'Housing', 1, 75, 1, 'Opposition', 'Opposition that disappeared when parking and school capacity were guaranteed would show this interest drives it.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, direction, bridge, bottom_line) VALUES (126, 'driver', 'Housing', 1, 16, 1, 'Opposition', 'Equal opposition to luxury and subsidized housing would show the driver is change, not income.', 'Does this interest actually drive the position, or only decorate it?');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, bridge, bottom_line) VALUES (127, 'equivalence', 'Housing', 1, 1, 35, 'Abolition removes all use and density rules; the belief removes one rule.', 'Same direction, different policy: not a merge candidate.');
INSERT INTO page (id, kind, topic, parent_id, x_id, y_id, bridge, bottom_line) VALUES (128, 'equivalence', 'Housing', 1, 1, 36, 'The moderate version adds "modestly" and restricts the claim to high-demand cities.', 'Close cousins; the moderate version is the belief with its scope stated.');
