INSERT INTO edge (id, page_id, section, position, attrs) VALUES (72, 1, 'definition', 1, '{"term": "Housing costs", "definition": "Median asking rent and median home price, adjusted for unit size, compared with the trend in matched cities."}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (73, 1, 'definition', 2, '{"term": "Single-family-only zoning", "definition": "Zoning that permits one detached dwelling per lot and prohibits duplexes or apartments."}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (74, 1, 'dispute', 1, 'Empirical', '{"what": "How much new supply lowers rents and how fast.", "move": "Multi-city natural experiments with controls."}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (75, 1, 'dispute', 2, 'Definitional', '{"what": "Whether \"housing costs\" means rents, prices, or the cost of a first home.", "move": "Agree to score rents and prices separately."}');
