INSERT INTO edge (id, page_id, section, side, position, text) VALUES (84, 2, 'argument', 'agree', 1, 'Auckland''s 2016 upzoning was followed by a permit surge concentrated in the upzoned areas, which is what a zoning effect looks like and a demand shock does not.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (85, 2, 'argument', 'agree', 2, 'Minneapolis diverged from the rest of Minnesota on both permits and rents after 2019, while sharing the state''s interest rates and economy.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (86, 2, 'argument', 'agree', 3, 'The pattern repeats across cities with different demand conditions (Auckland, Minneapolis, Austin, Houston), which is hard to explain by local booms alone.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (87, 2, 'argument', 'disagree', 1, 'The comparison cities differ in demand growth and land availability, so a matched-city design cannot fully separate zoning from growth.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (88, 2, 'argument', 'disagree', 2, 'Minneapolis also loosened rules on large apartment buildings along corridors, so the rent effect cannot be attributed to the single-family change alone.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (89, 2, 'argument', 'disagree', 3, 'Austin''s supply came from apartments on commercial land, not from single-family lots, so it tests a different reform.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (90, 2, 'evidence', 'agree', 1, 'Dwelling consents in Auckland''s upzoned areas rose sharply relative to trend after 2016; the study attributes an estimated 20,000-plus additional homes in five years to the reform.
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (91, 2, 'evidence', 'agree', 2, 10);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (92, 2, 'evidence', 'agree', 3, 'Austin-area asking rents fell more than 15 percent from their 2023 peak by 2025 after the metro led the nation in apartments permitted per resident.
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (93, 2, 'evidence', 'disagree', 1, 13);
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (94, 2, 'prediction', 'agree', 1, 'Minneapolis rents keep growing more slowly than the Minnesota average through 2028.', 'By 2028; Zillow rent index');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (95, 2, 'prediction', 'agree', 2, 'A difference-in-differences study across ten or more U.S. reform cities showing lower rent growth than matched controls.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (96, 2, 'prediction', 'disagree', 1, 'A reanalysis showing Minneapolis''s rent divergence began before 2019 or is explained by corridor apartments alone.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (97, 2, 'component', 1, 'Permits rose after reform in the reform cities.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes permit counts reflect homes actually built"}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (98, 2, 'component', 2, 'Rents grew more slowly than in comparable cities.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes the comparison cities are comparable"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (99, 2, 'assumption', 'agree', 1, 'The comparison cities would have followed the same path without reform.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (100, 2, 'assumption', 'disagree', 1, 'Local demand shocks happened to coincide with each reform.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (101, 2, 'obstacle', 'agree', 1, 'Few reforms are old enough to show a five-year record.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (102, 2, 'obstacle', 'disagree', 1, 'Every additional reform city that diverges from trend makes the coincidence story harder.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (103, 2, 'bias', 'agree', 1, 'Selecting the reform cities that worked.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (104, 2, 'bias', 'disagree', 1, 'Demanding a randomized trial for a policy that cannot be randomized.');
INSERT INTO edge (id, page_id, section, side, position, claim_id, attrs) VALUES (105, 2, 'media', 'agree', 1, 57, '{"type": "Article"}');
INSERT INTO edge (id, page_id, section, side, position, claim_id, attrs) VALUES (106, 2, 'media', 'disagree', 1, 58, '{"type": "Study"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (107, 2, 'definition', 1, '{"term": "Comparable cities", "definition": "Cities in the same state or region with similar income and population growth that did not reform in the period."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (108, 3, 'argument', 'agree', 1, 'In the most regulated metros the price of a home exceeds its construction cost by a large regulatory premium, while in lightly regulated metros price tracks construction cost.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (109, 3, 'argument', 'agree', 2, 'Metros that allow building (Houston, Atlanta, Dallas) absorbed large demand booms with prices near construction cost, which a demand-only story cannot explain.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (110, 3, 'argument', 'agree', 3, 'Where lots allow only one home, the land price per home is the whole lot, so the cap on units is what makes the land unaffordable.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (111, 3, 'argument', 'disagree', 1, 'Construction costs and financing, not zoning, are the binding constraint in many cities: hard costs rose faster than rents in 2015-2023.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (112, 3, 'argument', 'disagree', 2, 'In cities with weak demand, upzoning changes nothing because nobody wants to build; zoning binds only where demand already outruns supply.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (113, 3, 'evidence', 'agree', 1, 'Glaeser and Gyourko estimate that in the most regulated metros home prices exceed minimum profitable production cost by a large margin, while in lightly regulated metros the two are close.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (114, 3, 'evidence', 'agree', 2, 'Metros with elastic housing supply saw smaller price booms and smaller busts in the 2000s cycle.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (115, 3, 'evidence', 'disagree', 1, 'Multifamily hard construction costs in California rose by roughly a third to a half between 2015 and 2023, outpacing rents in most markets.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (116, 3, 'prediction', 'agree', 1, 'Metros that upzone broadly will show falling price-to-construction-cost ratios by 2030.', 'By 2030; replicate the 2018 method');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (117, 3, 'prediction', 'agree', 2, 'Price-to-construction-cost premiums shrinking in metros that upzoned.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (118, 3, 'prediction', 'disagree', 1, 'Upzoned metros with unchanged premiums after five years.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (119, 3, 'component', 1, 'Prices in high-cost metros exceed construction cost by a regulatory premium.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes the premium is regulation, not land scarcity alone"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (120, 3, 'assumption', 'agree', 1, 'Land would be used more intensively if the rules allowed it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (121, 3, 'assumption', 'disagree', 1, 'Construction capacity, not permission, limits building.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (122, 3, 'obstacle', 'agree', 1, 'The premium is an estimate, not a measurement.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (123, 3, 'obstacle', 'disagree', 1, 'The elastic-supply metros are a standing counterexample.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (124, 3, 'bias', 'agree', 1, 'Treating every cost gap as regulation.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (125, 3, 'bias', 'disagree', 1, 'Treating construction cost as fixed rather than responsive to volume.');
INSERT INTO edge (id, page_id, section, side, position, claim_id, attrs) VALUES (126, 3, 'media', 'agree', 1, 56, '{"type": "Study"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (127, 3, 'definition', 1, '{"term": "Binding constraint", "definition": "The limit that, if relaxed, would increase supply; other limits would not bind until it is relaxed."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (128, 4, 'argument', 'agree', 1, 'Studies of new buildings in several cities find rents in nearby existing buildings fall relative to controls after completion.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (129, 4, 'argument', 'agree', 2, 'Each new unit starts a chain of moves that reaches lower-income neighborhoods within a few steps.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (130, 4, 'argument', 'disagree', 1, 'New buildings can raise nearby rents through amenity effects, and some studies find increases in the lowest-rent buildings nearby.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (131, 4, 'argument', 'disagree', 2, 'The effects are local and small; they do not add up to citywide affordability.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (132, 4, 'evidence', 'agree', 1, 'New apartment buildings lowered rents in buildings within a few hundred meters by 1 to 6 percent relative to controls in New York, San Francisco and Helsinki.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (133, 4, 'evidence', 'agree', 2, 'Migration chains from new market-rate buildings reach below-median-income neighborhoods within about three moves.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (134, 4, 'evidence', 'disagree', 1, 'In Minneapolis, new market-rate buildings were followed by rent increases in the lowest-rent nearby buildings and decreases in higher-rent ones.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (135, 4, 'prediction', 'agree', 1, 'New multi-city studies published by 2028 will find nearby rents falling relative to controls.', 'By 2028; peer-reviewed literature');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (136, 4, 'prediction', 'agree', 2, 'Replication of the nearby-rent effect in Sun Belt metros.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (137, 4, 'prediction', 'disagree', 1, 'A multi-city study finding rent increases in the lowest-rent nearby buildings.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (138, 4, 'component', 1, 'Higher-income renters move into new buildings.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes new buildings are not filled from outside the city"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (139, 4, 'assumption', 'agree', 1, 'Renters move up when a better unit becomes available.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (140, 4, 'assumption', 'disagree', 1, 'New buildings attract residents who would otherwise not have moved to the city.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (141, 4, 'obstacle', 'agree', 1, 'The effect is small per building and hard to see without careful controls.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (142, 4, 'obstacle', 'disagree', 1, 'The amenity-effect studies are fewer and less replicated.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (143, 4, 'bias', 'agree', 1, 'Generalizing from dense coastal cities.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (144, 4, 'bias', 'disagree', 1, 'Reading local rent increases as caused by the building rather than by the neighborhood''s trend.');
INSERT INTO edge (id, page_id, section, side, position, text, attrs) VALUES (145, 4, 'media', 'agree', 1, 'Asquith, Mast and Reed, Review of Economics and Statistics (2023)', '{"type": "Study"}');
INSERT INTO edge (id, page_id, section, side, position, text, attrs) VALUES (146, 4, 'media', 'disagree', 1, 'Damiano and Frenier (2020)', '{"type": "Working paper"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (147, 4, 'definition', 1, '{"term": "Filtering", "definition": "The process by which housing passes to lower-income occupants as higher-income households move to newer units."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (148, 5, 'argument', 'agree', 1, 'Subsidized affordable units cost several hundred thousand dollars each in high-cost states; a zoning change costs staff time.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (149, 5, 'argument', 'agree', 2, 'Private capital builds the homes, so the tool scales with demand rather than with the budget.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (150, 5, 'argument', 'disagree', 1, 'Cheap for the city is not cheap for tenants displaced by redevelopment; the cost is shifted, not removed.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (151, 5, 'argument', 'disagree', 2, 'Without subsidy, new units rent at market rates and reach low-income households only slowly through filtering.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (152, 5, 'evidence', 'agree', 1, 'Publicly subsidized affordable apartments in California cost well over half a million dollars per unit in recent years.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (153, 5, 'evidence', 'disagree', 1, 'Filtering to low-income households takes decades in tight markets.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (154, 5, 'prediction', 'agree', 1, 'Reform cities will add homes at a lower public cost per unit than subsidy-led cities through 2030.', 'By 2030; budget and permit data');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (155, 5, 'prediction', 'agree', 2, 'Cost-per-unit comparisons across reform cities and subsidy programs.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (156, 5, 'prediction', 'disagree', 1, 'Evidence that reform cities spent heavily on infrastructure or displacement relief per new unit.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (157, 5, 'component', 1, 'Zoning reform costs the public little.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes no large infrastructure bills follow"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (158, 5, 'assumption', 'agree', 1, 'Affordability is measured by public cost per home added.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (159, 5, 'assumption', 'disagree', 1, 'Affordability is measured by homes reaching low-income households now.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (160, 5, 'obstacle', 'agree', 1, 'Market-rate units are a hard sell as an affordability tool.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (161, 5, 'obstacle', 'disagree', 1, 'Subsidy programs cannot reach the scale of the shortage.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (162, 5, 'bias', 'agree', 1, 'Counting only public cost.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (163, 5, 'bias', 'disagree', 1, 'Counting only immediate affordability.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (164, 5, 'definition', 1, '{"term": "Cheapest affordability tool", "definition": "Lowest public cost per additional home, holding quality constant."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (165, 6, 'argument', 'agree', 1, 'SB 9 produced a few hundred applications statewide in its first year, in a state that needs millions of homes.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (166, 6, 'argument', 'agree', 2, 'Small projects on single lots cannot spread fixed costs, so at 2022-2024 interest rates most did not pencil out.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (167, 6, 'argument', 'agree', 3, 'Where land is expensive, the existing house is worth more than the redevelopment margin, so owners do not sell.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (168, 6, 'argument', 'disagree', 1, 'Slow uptake in the first years is typical of zoning changes; Auckland''s permit surge built over three to five years.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (169, 6, 'argument', 'disagree', 2, 'SB 9 carried restrictions (owner-occupancy, local design rules) that other reforms avoid, so it tests a weak version of the policy.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (170, 6, 'argument', 'disagree', 3, 'Oregon''s and Minneapolis''s reforms produced steady middle-housing permits within two years.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (171, 6, 'evidence', 'agree', 1, 'Fewer than 500 SB 9 applications were filed statewide in the law''s first year, concentrated in a handful of cities.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (172, 6, 'evidence', 'agree', 2, 'Multifamily construction starts fell by roughly half nationally from 2022 to 2024 as financing costs rose.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (173, 6, 'evidence', 'disagree', 1, 'Auckland''s consent surge grew over three to five years after the 2016 change rather than appearing at once.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (174, 6, 'evidence', 'disagree', 2, 'Portland permitted several hundred middle-housing units within two years of its 2021 Residential Infill Project, rising each year.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (175, 6, 'prediction', 'agree', 1, 'California lot-split permits stay below 2,000 per year through 2027.', 'By 2027; Terner Center counts');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (176, 6, 'prediction', 'agree', 2, 'SB 9 counts still in the hundreds per year in 2026-2027.');
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (177, 6, 'prediction', 'disagree', 1, 'Portland middle-housing permits keep rising year over year through 2027.', 'By 2027; city permit data');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (178, 6, 'prediction', 'disagree', 2, 'SB 9 counts in the thousands per year after the 2024 amendments or a rate decline.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (179, 6, 'component', 1, 'Construction cost, not permission, decides whether a lot is redeveloped where land is expensive.', '{"type": "Causal", "stated": "Y", "lb": "Y", "assumes": "Assumes rents do not rise enough to cover costs"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (180, 6, 'assumption', 'agree', 1, 'Early-year counts predict long-run counts.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (181, 6, 'assumption', 'disagree', 1, 'Uptake follows an adoption curve and the first years understate it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (182, 6, 'obstacle', 'agree', 1, 'Every reform is different, so a failed one is easy to dismiss as badly designed.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (183, 6, 'obstacle', 'disagree', 1, 'California is the test everyone watches.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (184, 6, 'bias', 'agree', 1, 'Judging a ten-year policy by its second year.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (185, 6, 'bias', 'disagree', 1, 'Explaining away every disappointing count as a design flaw.');
INSERT INTO edge (id, page_id, section, side, position, text, attrs) VALUES (186, 6, 'media', 'agree', 1, 'Terner Center, SB 9 implementation reports (2023)', '{"type": "Report"}');
INSERT INTO edge (id, page_id, section, side, position, text, attrs) VALUES (187, 6, 'media', 'disagree', 1, 'Sightline Institute, middle housing permit trackers (2022-2024)', '{"type": "Analysis"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (188, 6, 'definition', 1, '{"term": "Upzoning alone", "definition": "Changing what may be built without changing construction cost, financing, or the permitting process."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (189, 7, 'argument', 'agree', 1, 'Upzoning raises the value of land because the land can now hold more homes; that shows up in existing home prices before anything is built.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (190, 7, 'argument', 'agree', 2, 'Redevelopment of older rental buildings evicts the tenants in them, whatever happens to average rents.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (191, 7, 'argument', 'disagree', 1, 'Studies of new construction find it lowers displacement risk for nearby low-income renters rather than raising it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (192, 7, 'argument', 'disagree', 2, 'A higher land value is a gain to the existing owner, the opposite of a cost to them; the cost falls on buyers.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (193, 7, 'argument', 'disagree', 3, 'Displacement is worst where nothing gets built and rents rise across the board.');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (194, 7, 'evidence', 'agree', 1, 13);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (195, 7, 'evidence', 'disagree', 1, 'New market-rate construction in San Francisco reduced the probability of displacement for nearby renters.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (196, 7, 'evidence', 'disagree', 2, 'In Auckland, rents in upzoned areas grew more slowly than elsewhere after consents rose.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (197, 7, 'prediction', 'agree', 1, 'Renters near new middle-housing projects in reform cities will show higher move-out rates than controls by 2028.', 'By 2028; address-history data');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (198, 7, 'prediction', 'agree', 2, 'Multi-city evidence of higher displacement rates near redevelopment of older rentals.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (199, 7, 'prediction', 'disagree', 1, 'Replication of the San Francisco displacement result in other cities.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (200, 7, 'component', 1, 'Upzoning raises land values.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes the option to build is priced in"}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (201, 7, 'component', 2, 'Higher land values displace lower-income residents.', '{"type": "Causal", "stated": "Y", "lb": "Y", "assumes": "Assumes redevelopment outpaces filtering"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (202, 7, 'assumption', 'agree', 1, 'Redevelopment happens fastest in the cheapest older buildings.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (203, 7, 'assumption', 'disagree', 1, 'New supply lowers rents enough to offset redevelopment losses.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (204, 7, 'obstacle', 'agree', 1, 'The best displacement studies point the other way.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (205, 7, 'obstacle', 'disagree', 1, 'Every redevelopment eviction is visible and every averted rent increase is not.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (206, 7, 'bias', 'agree', 1, 'Availability: evictions make the news, filtering does not.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (207, 7, 'bias', 'disagree', 1, 'Averaging away the people who lose their homes.');
INSERT INTO edge (id, page_id, section, side, position, claim_id, attrs) VALUES (208, 7, 'media', 'agree', 1, 58, '{"type": "Study"}');
INSERT INTO edge (id, page_id, section, side, position, text, attrs) VALUES (209, 7, 'media', 'disagree', 1, 'Pennington, Does Building New Housing Cause Displacement? (2021)', '{"type": "Working paper"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (210, 7, 'definition', 1, '{"term": "Displacement", "definition": "A move out of a neighborhood caused by rent increase, eviction or redevelopment rather than by choice."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (211, 8, 'argument', 'agree', 1, 'Street parking gets scarcer when parking minimums are dropped and more households share a block.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (212, 8, 'argument', 'agree', 2, 'Fast-growing districts see school crowding before new schools are funded.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (213, 8, 'argument', 'agree', 3, 'Residents chose a neighborhood with a particular form and did not consent to its change.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (214, 8, 'argument', 'disagree', 1, 'Most older neighborhoods have lost population since 1970 as households shrank, so their schools and pipes have spare capacity.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (215, 8, 'argument', 'disagree', 2, 'New residents pay taxes that fund the infrastructure they use; infill is cheaper to serve than sprawl.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (216, 8, 'evidence', 'agree', 1, 'Surveys in neighborhoods where parking minimums were removed report more on-street parking competition.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (217, 8, 'evidence', 'disagree', 1, 'Household size in the United States fell from about 3.1 in 1970 to about 2.5 by 2020, leaving many older neighborhoods with fewer residents than they were built for.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (218, 8, 'evidence', 'disagree', 2, 'Infrastructure costs per home are lower for infill than for greenfield development.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (219, 8, 'prediction', 'agree', 1, 'Upzoned neighborhoods in reform cities will need new school construction within ten years.', 'By 2032; district capital plans');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (220, 8, 'prediction', 'agree', 2, 'Systematic measurement of parking and school capacity before and after upzoning.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (221, 8, 'prediction', 'disagree', 1, 'Evidence that upzoned neighborhoods stayed within school and utility capacity.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (222, 8, 'component', 1, 'New residents impose net costs on existing residents.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes newcomers do not pay for what they use"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (223, 8, 'assumption', 'agree', 1, 'Existing residents have a claim on the neighborhood''s current form.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (224, 8, 'assumption', 'disagree', 1, 'Cities exist to be shared with people who arrive later.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (225, 8, 'obstacle', 'agree', 1, 'The costs are diffuse and hard to price.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (226, 8, 'obstacle', 'disagree', 1, 'Nobody likes circling for parking.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (227, 8, 'bias', 'agree', 1, 'Endowment effect over the neighborhood as it is.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (228, 8, 'bias', 'disagree', 1, 'Dismissing quality-of-life costs because they are hard to price.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (229, 8, 'definition', 1, '{"term": "Neighborhood character", "definition": "The built form, density and appearance of a neighborhood as experienced by its residents."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (230, 9, 'argument', 'agree', 1, 'Austin''s record permits were financed at 3 percent rates; permits fell by about half in 2024 when rates rose.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (231, 9, 'argument', 'agree', 2, 'Rents fell across many Sun Belt metros in 2023-2025, including ones that did not reform zoning.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (232, 9, 'argument', 'disagree', 1, 'Minneapolis''s rent divergence from the state began around 2017, before the boom and before the 2019 reform took effect.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (233, 9, 'argument', 'disagree', 2, 'Cheap money was national; only the cities that allowed building turned it into supply, which is the point.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (234, 9, 'evidence', 'agree', 1, 'Austin metro multifamily permits fell by roughly half from 2022 to 2024 as interest rates rose.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (235, 9, 'evidence', 'agree', 2, 'Asking rents fell year over year in most large Sun Belt metros in 2024, reform or not.
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (236, 9, 'evidence', 'disagree', 1, 10);
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (237, 9, 'prediction', 'agree', 1, 'Austin permits per resident will fall back to the national average by 2027.', 'By 2027; Census permits');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (238, 9, 'prediction', 'agree', 2, 'Evidence that reform-city rents track non-reform Sun Belt cities once permits are controlled for.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (239, 9, 'prediction', 'disagree', 1, 'Evidence that reform cities kept outbuilding peers after rates rose.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (240, 9, 'component', 1, 'The 2021-2022 boom was financed by low rates.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes rates were the main driver of the boom"}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (241, 9, 'component', 2, 'Low rates will not return.', '{"type": "Empirical", "stated": "N", "lb": "Y", "assumes": "Assumes 2020-2021 rates were a one-off"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (242, 9, 'assumption', 'agree', 1, 'Rents would have fallen in these cities regardless of zoning.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (243, 9, 'assumption', 'disagree', 1, 'Permission was necessary for the boom to become homes.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (244, 9, 'obstacle', 'agree', 1, 'Minneapolis timing does not fit the story.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (245, 9, 'obstacle', 'disagree', 1, 'Austin timing fits it well.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (246, 9, 'bias', 'agree', 1, 'Attributing everything to the macro cycle.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (247, 9, 'bias', 'disagree', 1, 'Attributing everything to zoning.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (248, 9, 'definition', 1, '{"term": "Repeatable", "definition": "Achievable again under ordinary financing conditions."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (249, 10, 'argument', 'agree', 1, 'The divergence coincides with the city''s reforms and with a permitting rate well above the state''s.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (250, 10, 'argument', 'agree', 2, 'No other Minnesota city with similar demand diverged from the state trend in the same period.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (251, 10, 'argument', 'disagree', 1, 'Minneapolis also loosened rules on large apartment buildings along corridors, so the rent effect cannot be attributed to the single-family change alone.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (252, 10, 'argument', 'disagree', 2, 'The divergence began around 2017, two years before the reform took effect, which points to causes that predate it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (253, 10, 'evidence', 'agree', 1, 'Minneapolis rents rose about 1 percent from 2017 to 2023 against about 14 percent statewide, while housing stock grew about 12 percent against about 4 percent statewide.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (254, 10, 'evidence', 'disagree', 1, 'Most of Minneapolis''s new units in 2019-2023 were in large corridor buildings, not on single-family lots.
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (255, 10, 'prediction', 'agree', 1, 'A peer-reviewed synthetic-control study of Minneapolis will find a rent effect of the 2019 reforms by 2027.', 'By 2027; published literature');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (256, 10, 'prediction', 'agree', 2, 'A synthetic-control study attributing the rent gap to the 2019 package.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (257, 10, 'prediction', 'disagree', 1, 'Evidence that the 2017-2019 gap was as large as the post-2019 gap.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (258, 10, 'component', 1, 'Minneapolis rents diverged from the state.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes the Zillow index tracks the rental stock"}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (259, 10, 'component', 2, 'The 2019 reforms caused the divergence.', '{"type": "Causal", "stated": "Y", "lb": "Y", "assumes": "Assumes no other 2017-2019 change explains it"}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (260, 10, 'assumption', 'agree', 1, 'The rest of Minnesota is a fair counterfactual for Minneapolis.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (261, 10, 'assumption', 'disagree', 1, 'A 2017 start rules out a 2019 cause.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (262, 10, 'obstacle', 'agree', 1, 'One city, one policy package, no randomization.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (263, 10, 'obstacle', 'disagree', 1, 'The permitting numbers are hard to explain without the reforms.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (264, 10, 'bias', 'agree', 1, 'Crediting the famous reform for everything.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (265, 10, 'bias', 'disagree', 1, 'Requiring a single cause.');
INSERT INTO edge (id, page_id, section, side, position, claim_id, attrs) VALUES (266, 10, 'media', 'agree', 1, 57, '{"type": "Article"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (267, 10, 'definition', 1, '{"term": "Corridor reforms", "definition": "Rules allowing larger apartment buildings along transit and commercial corridors, passed alongside the single-family change."}');
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (268, 11, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (269, 12, 'argument', 'agree', 1, 'Comparing the cost of reform against subsidy programs is a separate claim that the supply argument does not make.', 'Different conclusion');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (270, 12, 'argument', 'agree', 2, 'One argument is settled by price data; the other by public budgets per home added.', 'Different evidence');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (271, 12, 'argument', 'agree', 3, 'The cost comparison could hold (reform is cheap per home) even if the supply effect turned out small; a restatement could not.', 'Independent failure');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (272, 12, 'argument', 'disagree', 1, 'The cheapest-tool claim rests on the same supply mechanism as the binding-constraint argument; only the cost comparison is new.', 'Shared premise');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (273, 12, 'argument', 'disagree', 2, 'If the supply mechanism fails, both arguments fail together, which is the mark of a restatement.', 'Stand or fall together');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (274, 12, 'related', 'x', 1, 2);
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (275, 12, 'related', 'x', 2, 4);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (276, 13, 'argument', 'agree', 1, 'Transaction prices rose in the upzoned parcels relative to controls within five years while permits did not.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (277, 13, 'argument', 'agree', 2, 'The result is what economic theory predicts for a small upzoning: the option value is priced in before anyone builds.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (278, 13, 'argument', 'disagree', 1, 'The Chicago changes were small and confined to narrow corridors, which limits what they show about citywide reform.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (279, 13, 'argument', 'disagree', 2, 'Five years is short for construction to respond, and the parcels were already among the most expensive in the city.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (280, 13, 'evidence', 'agree', 1, 'Parcels upzoned in 2013 and 2015 showed higher transaction prices than controls and no measurable increase in permits through 2018.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (281, 13, 'evidence', 'disagree', 1, 'Citywide reforms (Auckland, Minneapolis) that changed rules on most residential land were followed by permit surges that Chicago''s corridor changes were not.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (282, 13, 'prediction', 'agree', 1, 'Replication of the price-without-construction result in other small upzonings.');
INSERT INTO edge (id, page_id, section, side, position, text, deadline) VALUES (283, 13, 'prediction', 'disagree', 1, 'Chicago''s 2013-2015 corridor parcels will show more construction than controls by 2028.', 'By 2028; parcel permit data');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (284, 13, 'prediction', 'disagree', 2, 'Later Chicago data showing construction catching up after 2018.');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (285, 13, 'component', 1, 'Prices rose in upzoned parcels.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes controls were comparable"}');
INSERT INTO edge (id, page_id, section, position, text, attrs) VALUES (286, 13, 'component', 2, 'Construction did not rise.', '{"type": "Empirical", "stated": "Y", "lb": "Y", "assumes": "Assumes five years is long enough to see it"}');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (287, 13, 'definition', 1, '{"term": "Corridor upzoning", "definition": "A zoning change limited to parcels along particular streets or transit lines."}');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (288, 14, 'argument', 'agree', 1, 'If neighborhood costs get reforms repealed, the policy never lowers anything, so the costs bear on the outcome through politics.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (289, 14, 'argument', 'agree', 2, 'Infrastructure charges get passed into the price of new homes, so capacity costs are housing costs.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (290, 14, 'argument', 'disagree', 1, 'Whether existing residents bear costs does not bear on whether housing costs fall, which is the claim on the parent page; it belongs on the cost side of the cost-benefit table.', 'Wrong parent');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (291, 14, 'argument', 'disagree', 2, 'The argument answers a different question (is the reform worth it?) than the parent asks (does it lower costs?).', 'True but irrelevant');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (292, 14, 'argument', 'disagree', 3, 'The costs listed fall on existing residents of particular blocks; the belief is about housing costs across a city.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (293, 14, 'assumption', 'agree', 1, 'Infrastructure charges are passed through into home prices rather than absorbed by the added tax base.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (294, 14, 'assumption', 'disagree', 1, 'Housing costs means rents and prices, not total welfare of existing residents.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (295, 14, 'bias', 'agree', 1, 'Loss aversion among current residents makes every local cost feel like a citywide one.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (296, 14, 'bias', 'disagree', 1, 'Pro-housing editors dismiss any cost they cannot price.');
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (297, 15, 'interest_listing', 1, 75);
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (298, 16, 'argument', 'agree', 1, 'Preferring neighbors like oneself is a common feeling, stated openly in some testimony and implied in more.', 'Widely held');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (299, 16, 'argument', 'disagree', 1, 'Keeping people out by income is a claim to control who may live where, which nobody is entitled to.', 'Claim on others'' property or choices');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (300, 16, 'argument', 'disagree', 2, 'Fair housing law forbids exclusion by race and, in several states, by source of income; the need has no legal standing.', 'Forbidden by law');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (301, 16, 'argument', 'disagree', 3, 'The stated concerns (traffic, parking, character) often stand in for this one, which is why it rarely appears in testimony under its own name.', 'Pretext for another aim');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (302, 17, 'argument', 'agree', 1, 'The regulatory premium it measures is what ending single-family-only zoning would cut.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (303, 17, 'argument', 'disagree', 1, 'It is about regulation in general, not single-family zoning in particular.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (304, 18, 'argument', 'agree', 1, 'Minneapolis and Auckland both show rent gaps against their regions of that order or larger within five years.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (305, 18, 'argument', 'agree', 2, 'Spillover studies find 1 to 6 percent local effects per building, which accumulate as buildings accumulate.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (306, 18, 'argument', 'disagree', 1, 'The effect appears only where building follows; in cities with weak demand or high costs the number is near zero.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (307, 18, 'argument', 'disagree', 2, 'Five years is early; most of the gap in Auckland opened after year three.');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (308, 18, 'evidence', 'agree', 1, 10);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (309, 18, 'evidence', 'disagree', 1, 'SB 9 added too few homes to move any rent index.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (310, 18, 'prediction', 'agree', 1, 'A multi-city estimate at or above 5 percent.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (311, 18, 'prediction', 'disagree', 1, 'A multi-city estimate near zero.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (312, 18, 'definition', 1, '{"term": "Counterfactual rent", "definition": "The rent the city would have had without the reform, estimated from matched cities."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (313, 19, 'argument', 'agree', 1, 'Auckland added on the order of 4,000 extra homes a year in a city of 1.6 million, about 2.5 per 1,000.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (314, 19, 'argument', 'agree', 2, 'Minneapolis outbuilt the state by several units per 1,000 residents per year after 2019.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (315, 19, 'argument', 'disagree', 1, 'California''s lot-split law added a small fraction of a home per 1,000 residents.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (316, 19, 'evidence', 'agree', 1, 'An estimated 20,000-plus additional homes over five years in Auckland.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (317, 19, 'evidence', 'disagree', 1, 'Fewer than 500 SB 9 applications statewide in year one, in a state of 39 million.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (318, 19, 'definition', 1, '{"term": "Additional homes", "definition": "Homes built beyond the matched-city trend, not total homes built."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (319, 20, 'argument', 'agree', 1, 'Households in central, walkable neighborhoods drive substantially less than households at the urban edge.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (320, 20, 'argument', 'disagree', 1, 'The comparison assumes the new residents would otherwise have lived at the edge rather than not moving at all.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (321, 20, 'evidence', 'agree', 1, 'Household vehicle miles fall with density and centrality; central households drive roughly 20 to 40 percent less than edge households in the same metro.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (322, 20, 'definition', 1, '{"term": "Infill", "definition": "Housing built within the existing urban footprint rather than at its edge."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (323, 21, 'argument', 'agree', 1, 'More competing homes lower the price of existing ones, all else equal.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (324, 21, 'argument', 'disagree', 1, 'Upzoning raises the land value under existing homes, and in most studies the net effect on existing owners is positive.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (325, 21, 'evidence', 'agree', 1, 'Owners near new construction report concern about resale values in surveys.
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (326, 21, 'evidence', 'disagree', 1, 13);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (327, 21, 'evidence', 'disagree', 2, 'Auckland land values rose in upzoned areas after 2016.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (328, 21, 'definition', 1, '{"term": "Where new homes compete", "definition": "Neighborhoods in which new units are close substitutes for existing detached homes."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (329, 22, 'argument', 'agree', 1, 'Redeveloping an occupied older rental evicts its tenants, and small-lot redevelopment targets exactly those buildings.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (330, 22, 'argument', 'disagree', 1, 'New construction lowers displacement risk for nearby renters in the studies that measure it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (331, 22, 'argument', 'disagree', 2, 'Most middle-housing projects replace single-family homes, not occupied rentals.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (332, 22, 'evidence', 'disagree', 1, 'New market-rate construction reduced nearby renters'' probability of displacement.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (333, 22, 'definition', 1, '{"term": "Displaced household", "definition": "A household that moves because its building is demolished or its rent rises beyond its means."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (334, 23, 'argument', 'agree', 1, 'Utilities sized for 1970 household counts need upgrades where infill is concentrated.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (335, 23, 'argument', 'disagree', 1, 'Infill is the cheapest development to serve; cost-of-service studies put it well below greenfield.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (336, 23, 'argument', 'disagree', 2, 'Impact fees and the added tax base cover most infrastructure costs of infill.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (337, 23, 'evidence', 'disagree', 1, 'Per-unit infrastructure cost for infill is a fraction of the greenfield figure in municipal cost-of-service studies.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (338, 23, 'definition', 1, '{"term": "Built-out neighborhood", "definition": "A neighborhood with no vacant land, where new homes replace or add to existing buildings."}');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (339, 24, 'argument', 'agree', 1, 'Shelter is a basic need, and paying more than a third of income for it crowds out food, health and savings.', 'Basic need');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (340, 24, 'argument', 'agree', 2, 'The need is met by a market that builds enough homes; it asks nothing from anyone''s pocket.', 'Asks no transfer from others');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (341, 24, 'argument', 'agree', 3, 'About half of renters pay more than 30 percent of income for housing, so the need is common, not a niche.', 'Widely held');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (342, 24, 'argument', 'disagree', 1, 'Everyone wants lower prices for what they buy; wanting it does not by itself create a claim on how others use their land.', 'Claim on others'' property or choices');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (343, 25, 'argument', 'agree', 1, 'For most owners the home is the family''s savings and its security in old age; a loss there is a loss of security, not of luxury.', 'Basic need');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (344, 25, 'argument', 'agree', 2, 'Two thirds of households own their home, and most of their wealth is in it.', 'Widely held');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (345, 25, 'argument', 'disagree', 1, 'Protecting a home''s value by controlling what neighbors may build on their own lots is a claim on other people''s property.', 'Claim on others'' property or choices');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (346, 25, 'argument', 'disagree', 2, 'Home values in the high-cost metros the belief is about have risen far faster than incomes for decades; the need for protection is a need to keep a windfall.', 'Already met');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (347, 26, 'argument', 'agree', 1, 'Fourplexes by right add supply everywhere at once, which spreads change thinly instead of concentrating it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (348, 26, 'argument', 'agree', 2, 'Design standards address the character concern that drives most opposition.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (349, 26, 'argument', 'agree', 3, 'Oregon and Minneapolis adopted versions of this and neither reversed it.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (350, 26, 'argument', 'disagree', 1, 'Four units without parking reform produces little where lots are small; the parking rule does most of the work and is the most contested part.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (351, 26, 'argument', 'disagree', 2, 'Homeowner majorities on councils have blocked or watered down every such package in most cities that tried.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (352, 26, 'evidence', 'agree', 1, 'Oregon HB 2001 (2019) required cities over 25,000 to allow fourplexes; no repeal effort has succeeded.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (353, 26, 'definition', 1, '{"term": "By right", "definition": "Permitted without a discretionary hearing if the project meets the written standards."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (354, 27, 'argument', 'agree', 1, 'Across metros, those that build more have lower price growth for the same demand growth.');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (355, 27, 'argument', 'agree', 2, 4);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (356, 27, 'argument', 'disagree', 1, 'Induced demand: new supply attracts new residents, so prices do not fall.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (357, 27, 'argument', 'disagree', 2, 'In superstar cities demand is so deep that any feasible supply is a rounding error.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (358, 27, 'evidence', 'agree', 1, 'Elastic-supply metros had smaller price booms in the 2000s.
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (359, 27, 'evidence', 'disagree', 1, 'Some studies find new residents arrive faster than units in the most desirable metros.
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (360, 27, 'definition', 1, '{"term": "Induced demand", "definition": "Additional demand that appears because supply was added."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (361, 28, 'argument', 'agree', 1, 'Housing is a need before it is an asset, and policy that protects asset values by keeping people out inverts the priority.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (362, 28, 'argument', 'disagree', 1, 'Owners made the largest purchase of their lives under the existing rules and have a reliance interest in them.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (363, 28, 'definition', 1, '{"term": "Normative component", "definition": "A claim about what should count, argued by values rather than measured."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (364, 29, 'argument', 'agree', 1, 'Where permission was granted broadly (Auckland, Minneapolis, Portland) builders built.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (365, 29, 'argument', 'disagree', 1, 'At high interest rates and construction costs, permission is not enough; California''s lot-split law shows builders staying home.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (366, 29, 'definition', 1, '{"term": "Respond to permission", "definition": "Build more when the rules allow more, without a subsidy."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (367, 30, 'argument', 'agree', 1, 'New units rent at the top of the market and their first occupants are higher-income.');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (368, 30, 'argument', 'disagree', 1, 4);
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (369, 30, 'definition', 1, '{"term": "Filtering down", "definition": "Housing passing to lower-income households as higher-income households move to newer units."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (370, 31, 'argument', 'agree', 1, 'Developers and their trade groups fund a share of pro-housing campaigns and stand to gain from higher land values.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (371, 31, 'argument', 'disagree', 1, 'Most pro-housing advocates are renters and researchers with no stake in development returns.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (372, 31, 'definition', 1, '{"term": "Actual driver", "definition": "The interest that best predicts who takes the position."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (373, 32, 'argument', 'agree', 1, 'Opposition intensity tracks home values and homeownership rates more closely than stated concerns about traffic or design.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (374, 32, 'argument', 'disagree', 1, 'Many opponents are long-time renters and residents with no equity at stake who value the neighborhood as it is.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (375, 32, 'definition', 1, '{"term": "Actual driver", "definition": "The interest that best predicts who takes the position."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (376, 33, 'argument', 'agree', 1, 'Auckland''s rent effect took three to five years to appear; council terms are shorter than that.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (377, 33, 'argument', 'disagree', 1, 'Permit counts rise within a year and give reformers something to point to.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (378, 33, 'definition', 1, '{"term": "Sustain", "definition": "Keep a reform in force through subsequent elections."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (379, 34, 'argument', 'agree', 1, 'Rent control and subsidies have not made any high-demand city affordable without supply growth.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (380, 34, 'argument', 'disagree', 1, 'Vienna''s social housing is a standing example of affordability delivered by public building rather than by upzoning.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (381, 34, 'definition', 1, '{"term": "Fixed affordability", "definition": "Brought median rent below 30 percent of median income and kept it there."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (382, 35, 'argument', 'agree', 1, 'Houston, with no use zoning, has kept prices near construction cost through decades of growth.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (383, 35, 'argument', 'disagree', 1, 'Houston regulates through deed restrictions, minimum lot sizes and parking rules; it is not unzoned.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (384, 35, 'argument', 'disagree', 2, 'Abolition removes protections against noxious uses that most residents want.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (385, 35, 'definition', 1, '{"term": "Zoning", "definition": "Rules assigning permitted uses and densities to parcels."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (386, 36, 'argument', 'agree', 1, 'Every reform with a measured rent effect was in a high-demand city; low-demand cities show no change.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (387, 36, 'argument', 'disagree', 1, 'Modestly undersells Auckland and Minneapolis, where the gaps ran to double digits.');
INSERT INTO edge (id, page_id, section, position, attrs) VALUES (388, 36, 'definition', 1, '{"term": "High-demand city", "definition": "A city where prices exceed construction cost by a large margin."}');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (389, 37, 'argument', 'agree', 1, 'The study uses a difference-in-differences design with non-upzoned areas as controls and finds a sharp, sustained rise in consents.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (390, 37, 'argument', 'disagree', 1, 'Consents are not completions, and some of the surge may be displaced from areas that were not upzoned.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (391, 37, 'evidence', 'agree', 1, 'Greenaway-McGrevy and Phillips, Journal of Urban Economics (2023): peer-reviewed estimate of 20,000-plus additional dwellings attributable to the Unitary Plan.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (392, 38, 'argument', 'agree', 1, 'Census permit data and two independent rent indexes agree on the direction and rough size.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (393, 38, 'argument', 'disagree', 1, 'Asking-rent indexes overstate declines for sitting tenants, and the peak was inflated by 2021-2022 in-migration.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (394, 38, 'evidence', 'agree', 1, 'Census Building Permits Survey, metro multifamily permits per capita (2021-2023); Apartment List and Zillow asking-rent indexes (2023-2025).');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (395, 39, 'argument', 'agree', 1, 'Three independent teams using different data reached the same sign and a similar range.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (396, 39, 'argument', 'disagree', 1, 'One Minneapolis study finds the opposite sign for the cheapest nearby buildings.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (397, 39, 'evidence', 'agree', 1, 'Asquith, Mast and Reed (2023); Pennington (2021); Bratu, Harjunen and Saarimaa (2023).');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (398, 39, 'evidence', 'disagree', 1, 'Damiano and Frenier (2020), Minneapolis.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (399, 40, 'argument', 'agree', 1, 'The Terner count comes from a survey of the state''s largest cities and matches later HCD reporting.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (400, 40, 'argument', 'disagree', 1, 'Small cities were not all surveyed, so the true count is somewhat higher.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (401, 40, 'evidence', 'agree', 1, 'Terner Center for Housing Innovation, SB 9 implementation reports (2023).');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (402, 41, 'argument', 'agree', 1, 'It documents the rent and supply divergence after the 2019 reforms in a city that did what the belief names.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (403, 41, 'argument', 'disagree', 1, 'It does not separate the single-family change from the parking and density reforms that landed with it.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (404, 42, 'argument', 'agree', 1, 'It shows upzoning raising prices without construction, the belief''s outcome reversed.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (405, 42, 'argument', 'disagree', 1, 'Its corridor upzonings were small; it says little about citywide reform.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (406, 43, 'argument', 'agree', 1, 'The option to build more is priced into land the day the rule changes.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (407, 43, 'argument', 'disagree', 1, 'Where nobody expects to build, the option is worth nothing and land does not move.');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (408, 43, 'evidence', 'agree', 1, 13);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (409, 44, 'argument', 'agree', 1, 'Portland and Minneapolis saw applications within the first year; Auckland within two.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (410, 44, 'argument', 'disagree', 1, 'California''s lot-split law shows that restrictive design rules can hold applications near zero.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (411, 45, 'argument', 'agree', 1, 'Auckland''s rent divergence widened through year five as consents became completions.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (412, 45, 'argument', 'disagree', 1, 'No reform is old enough to show a full decade yet.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (413, 46, 'argument', 'agree', 1, 'Every reformed city shows some teardown-to-multiplex activity, concentrated on the most valuable lots.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (414, 46, 'argument', 'disagree', 1, 'The pace is slow: a few percent of lots per decade in the busiest cities.');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (415, 47, 'argument', 'agree', 1, 'Producing what buyers want is the ordinary business of any trade; the need is for permission, not subsidy.', 'Asks no transfer from others');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (416, 47, 'argument', 'agree', 2, 'The right to build on one''s own land within the rules is a recognized property right.', 'Recognized in law');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (417, 47, 'argument', 'disagree', 1, 'Builders profit from land value uplift whether or not costs fall, so the stated need for permission partly covers a need for returns.', 'Pretext for another aim');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (418, 47, 'argument', 'disagree', 2, 'Builders are a small trade; the need is real but narrow.', 'Held by few');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (419, 48, 'argument', 'agree', 1, 'Losing one''s home to redevelopment is a serious harm, and it falls on people with the fewest options.', 'Basic need');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (420, 48, 'argument', 'agree', 2, 'Relocation assistance and just-cause eviction rules already recognize the need in many cities.', 'Recognized in law');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (421, 48, 'argument', 'disagree', 1, 'The fear is sometimes raised by owners in neighborhoods where displacement risk is lowest, to block housing for others.', 'Pretext for another aim');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (422, 48, 'argument', 'disagree', 2, 'Where just-cause and relocation rules exist, the need is met by those rules rather than by blocking new homes.', 'Already met');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (423, 49, 'argument', 'agree', 1, 'Polling on housing consistently finds this concern shared across owners and renters.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (424, 49, 'argument', 'disagree', 1, 'Some owners would rather their children inherit a valuable house elsewhere than an affordable one nearby.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (425, 50, 'argument', 'agree', 1, 'Supporters predicted large SB 9 output that did not appear.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (426, 50, 'argument', 'disagree', 1, 'Most supporters also push for permitting and financing reform, which shows they do not think permission is enough.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (427, 51, 'argument', 'agree', 1, 'Opposition intensity tracks home equity, and owners weigh a possible loss far more than an equal gain.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (428, 51, 'argument', 'disagree', 1, 'Preferring the neighborhood one chose is a preference, not a bias.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (429, 52, 'argument', 'agree', 1, 'Early reformers (Minneapolis, Auckland) are already below trend.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (430, 52, 'argument', 'disagree', 1, 'The 2021-2022 boom cities may revert as financing stays expensive.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (431, 53, 'argument', 'agree', 1, 'Most of the 2023-2025 rent declines happened in Sun Belt cities regardless of zoning.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (432, 53, 'argument', 'disagree', 1, 'Minneapolis diverged from its state under the same rates and a shrinking population.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (433, 54, 'argument', 'agree', 1, 'Confirmed: about 1 percent versus about 14 percent, 2017-2023 (Pew 2024).');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (434, 54, 'argument', 'disagree', 1, 'The divergence began in 2017, so part of it predates the reform.');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (435, 54, 'evidence', 'agree', 1, 10);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (436, 55, 'argument', 'agree', 1, 'Advocates projected large output from the state''s millions of eligible lots.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (437, 55, 'argument', 'disagree', 1, 'Disconfirmed: a few hundred applications statewide in the first years (Terner Center 2023).');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (438, 55, 'evidence', 'disagree', 1, 40);
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (439, 56, 'argument', 'agree', 1, 'Builds the regulatory premium from construction cost and price data, metro by metro.', 'Primary sources');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (440, 56, 'argument', 'agree', 2, 'The gap between price and construction cost is a clean measure of what permission costs.', 'Well reasoned');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (441, 56, 'argument', 'disagree', 1, 'It treats regulation as the whole gap and gives little room to land scarcity that no rule created.', 'One-sided');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (442, 56, 'impact', 'agree', 1, 'The regulatory-premium framing appears in most later work on zoning and prices.', 'Widely cited');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (443, 56, 'impact', 'agree', 2, 'Cited in state housing bills and federal housing plans.', 'Shaped policy');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (444, 56, 'impact', 'disagree', 1, 'Read mainly by economists already persuaded that supply matters.', 'Preaching to the converted');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (445, 57, 'argument', 'agree', 1, 'Its rent and permit figures match the Census and Zillow series it draws on.', 'Accurate');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (446, 57, 'argument', 'disagree', 1, 'A descriptive comparison with the state, not a causal study; several reforms landed at once.', 'Weak reasoning');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (447, 57, 'impact', 'agree', 1, 'The Minneapolis story is the case most journalists and councils cite.', 'Reached a broad audience');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (448, 57, 'impact', 'disagree', 1, 'Little academic work builds on it; it is a summary, not a study.', 'Rarely cited');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (449, 58, 'argument', 'agree', 1, 'Parcel-level transaction and permit data before and after two upzonings.', 'Primary sources');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (450, 58, 'argument', 'agree', 2, 'A difference-in-differences design with untouched parcels as controls.', 'Well reasoned');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (451, 58, 'argument', 'disagree', 1, 'Five years is short for construction to follow; the paper reads a lag as a null.', 'One-sided');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (452, 58, 'impact', 'agree', 1, 'The standard citation for the claim that upzoning raises prices without adding homes.', 'Widely cited');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (453, 58, 'impact', 'disagree', 1, 'Known in planning circles; little reach beyond them.', 'Small audience');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (454, 59, 'argument', 'agree', 1, 'Each law''s findings section cites housing costs as the purpose.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (455, 59, 'argument', 'disagree', 1, 'Legislative findings are political statements, not evidence that the policy works.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (456, 60, 'argument', 'agree', 1, 'Cities keep discretionary review and design rules that can null a state reform, as SB 9 showed.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (457, 60, 'argument', 'disagree', 1, 'States have been overriding local rules faster each year.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (458, 61, 'argument', 'agree', 1, 'Basic price theory, confirmed across goods and across housing markets with elastic supply.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (459, 61, 'argument', 'disagree', 1, 'Housing is durable and location-bound, so supply responds slowly and unevenly.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (460, 62, 'argument', 'agree', 1, 'Residents bear the local effects and know the place best.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (461, 62, 'argument', 'disagree', 1, 'Local control lets incumbents exclude newcomers who have no vote there.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (462, 63, 'argument', 'agree', 1, 'Parking minimums add tens of thousands of dollars per unit and are unused near transit.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (463, 63, 'argument', 'disagree', 1, 'Spillover parking burdens neighbors without permit systems.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (464, 64, 'argument', 'agree', 1, 'Irreplaceable building stock deserves protection.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (465, 64, 'argument', 'disagree', 1, 'Historic designation is used to freeze whole neighborhoods, not to protect buildings.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (466, 65, 'argument', 'agree', 1, 'Decades of published work say so (Glaeser and Gyourko 2018 among others).');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (467, 66, 'argument', 'agree', 1, 'Its Minneapolis and Auckland analyses draw that conclusion.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (468, 66, 'argument', 'disagree', 1, 'Pew frames its work as analysis rather than advocacy.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (469, 67, 'argument', 'agree', 1, 'Its public positions and testimony opposed both bills.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (470, 68, 'argument', 'agree', 1, 'His 2020 Chicago study says exactly that for corridor upzonings.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (471, 68, 'argument', 'disagree', 1, 'He has also written in favor of broad zoning reform, so the record is nuanced.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (472, 69, 'argument', 'agree', 1, 'Auckland''s and Minneapolis''s rent gaps widened over their first five years, which is the pattern such a study would find if it holds generally.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (473, 69, 'argument', 'disagree', 1, 'No multi-city study with matched controls has been published yet, so the prediction is pending.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (474, 70, 'argument', 'agree', 1, 'Where consents rose sharply (Auckland), land value per home fell as lots were split, which is the premium shrinking.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (475, 70, 'argument', 'disagree', 1, 'Construction costs rose faster than prices in 2020-2024, which shrinks the measured premium without any price falling.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (476, 71, 'argument', 'agree', 1, 'Rents fell across the Sun Belt in 2023-2025 in cities that reformed nothing.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (477, 71, 'argument', 'disagree', 1, 'Minneapolis diverged from its state before the boom and under the same interest rates.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (478, 72, 'argument', 'agree', 1, 'Teardowns in high-value neighborhoods often replace a small house with a large one under any zoning.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (479, 72, 'argument', 'disagree', 1, 'Portland and Minneapolis permit data show most redeveloped lots taking two to four units where that is allowed.');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (480, 73, 'argument', 'agree', 1, 'A place to live near work and family is shelter, the most basic need on the list.', 'Basic need');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (481, 73, 'argument', 'agree', 2, 'The need is for homes to exist, not for anyone to give one up.', 'Asks no transfer from others');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (482, 73, 'argument', 'disagree', 1, 'People who do not yet live in a city have no standing in its decisions, on the view that a city belongs to its residents.', 'Held by few');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (483, 73, 'argument', 'disagree', 2, 'Making room for newcomers means changing the neighborhoods current residents chose.', 'Claim on others'' property or choices');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (484, 74, 'argument', 'agree', 1, 'Long car commutes cost hours, sleep and clean air, and edge growth adds driving for everyone in the region.', 'Basic need');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (485, 74, 'argument', 'agree', 2, 'Every household in the region breathes the air and sits in the traffic that edge growth produces.', 'Widely held');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (486, 74, 'argument', 'disagree', 1, 'Climate is sometimes invoked to justify density that the invoker wants for other reasons.', 'Pretext for another aim');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (487, 74, 'argument', 'disagree', 2, 'Most residents rank their own commute above regional emissions, so the need as stated is held intensely by few.', 'Held by few');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (488, 75, 'argument', 'agree', 1, 'Parking, school crowding and a changed streetscape are what residents actually experience day to day.', 'Widely held');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (489, 75, 'argument', 'agree', 2, 'Zoning itself exists in law to protect settled expectations about what a neighborhood will be.', 'Recognized in law');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (490, 75, 'argument', 'disagree', 1, 'Keeping a neighborhood as it is means deciding what neighbors may build on their own lots.', 'Claim on others'' property or choices');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (491, 75, 'argument', 'disagree', 2, 'Street parking is a public asset given away free; a need to keep it is a need to keep a subsidy.', 'Already met');
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (492, 76, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id, bearing_id) VALUES (493, 76, 'interest_listing', 2, 47, 96);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (494, 76, 'assumption', 'agree', 1, 'The rent and permit readings in the reform cities are the readings the belief is about.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (495, 76, 'bias', 'agree', 1, 'Treating the best-known reform cities as the whole story.');
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (496, 77, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (497, 77, 'interest_listing', 2, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (498, 78, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (499, 78, 'interest_listing', 2, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (500, 79, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (501, 79, 'interest_listing', 2, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (502, 80, 'interest_listing', 1, 25);
INSERT INTO edge (id, page_id, section, position, claim_id, bearing_id) VALUES (503, 80, 'interest_listing', 2, 48, 97);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (504, 81, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (505, 82, 'interest_listing', 1, 47);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (506, 82, 'interest_listing', 2, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (507, 83, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (508, 84, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (509, 85, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (510, 86, 'interest_listing', 1, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (511, 86, 'interest_listing', 2, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (512, 87, 'interest_listing', 1, 25);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (513, 87, 'interest_listing', 2, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (514, 88, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (515, 89, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (516, 90, 'interest_listing', 1, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (517, 91, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (518, 92, 'interest_listing', 1, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (519, 93, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (520, 94, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (521, 95, 'interest_listing', 1, 73);
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (522, 96, 'argument', 'agree', 1, 'The reason states outright that permits rose, and a permit is a builder getting permission to build.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (523, 96, 'argument', 'disagree', 1, 'The reason''s payload is the rent comparison; builders appear only as the mechanism, not as the people it is about.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (524, 97, 'argument', 'agree', 1, 'Redevelopment that displaces lower-income renters and owners is exactly the harm this need names.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (525, 97, 'argument', 'disagree', 1, 'The reason is about land values raising the price of existing homes; displacement is asserted at the end, not shown.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (526, 98, 'argument', 'agree', 1, 'Slower rent growth in reform cities than in comparable cities is the belief''s own claim measured directly, so the reason bears on it as directly as evidence can.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (527, 98, 'argument', 'agree', 2, 'The reason and the belief are about the same cities, the same period and the same quantity (rents), so nothing has to be stretched.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (528, 98, 'argument', 'disagree', 1, 'Comparable cities are chosen after the fact, so the reason can be true while the causal claim is not; the linkage is only as good as the matching.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (529, 98, 'related', 'y', 1, 99);
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (530, 98, 'related', 'y', 2, 100);
INSERT INTO edge (id, page_id, section, side, position, claim_id) VALUES (531, 98, 'related', 'y', 3, 14);
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (532, 98, 'assumption', 'agree', 1, 'The comparison cities would have followed the reform cities'' path without reform.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (533, 98, 'assumption', 'agree', 2, 'Permits in reform cities became completed homes.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (534, 98, 'assumption', 'disagree', 1, 'Reform cities were selected for the comparison because they succeeded.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (535, 98, 'bias', 'agree', 1, 'Motivated reasoning toward the belief among pro-housing editors.');
INSERT INTO edge (id, page_id, section, side, position, text) VALUES (536, 98, 'bias', 'disagree', 1, 'Demanding a randomized trial for a policy that cannot be randomized.');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (537, 99, 'argument', 'agree', 1, 'If zoning is the binding constraint, relaxing it is what changes supply, and supply is what moves prices; the reason is the causal spine of the belief.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (538, 99, 'argument', 'agree', 2, 'High-cost metros are exactly where the belief''s cities are, so the constraint claim and the belief cover the same places.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (539, 99, 'argument', 'disagree', 1, 'A constraint can bind without one particular reform relaxing it enough to matter; the reason establishes the mechanism, not the size of the effect.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (540, 100, 'argument', 'agree', 1, 'Spillover is how new market-rate homes reach renters in older buildings, which is where most of a city''s housing costs are paid.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (541, 100, 'argument', 'disagree', 1, 'The result concerns individual new buildings; it does not by itself show that a citywide zoning change produces enough of them to move citywide costs.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (542, 101, 'argument', 'agree', 1, 'Adding homes without subsidy is a route to lower costs that does not depend on budgets, so the reason bears on whether costs fall in practice.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (543, 101, 'argument', 'disagree', 1, 'Cheapness is about what the reform costs the public, not about whether it lowers housing costs; the reason answers a different question.', 'Wrong parent');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (544, 101, 'argument', 'disagree', 2, 'A tool can be cheap and still fail to lower costs; cheapness says nothing about the size of the effect.', 'True but irrelevant');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (545, 102, 'argument', 'agree', 1, 'If reform produces few homes, it cannot lower costs through supply, so the reason strikes at the belief''s mechanism.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (546, 102, 'argument', 'disagree', 1, 'SB 9 is one narrow reform in one state; a low count there weakens the belief for that design, not for reforms in general.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (547, 103, 'argument', 'agree', 1, 'Higher prices for existing homes are a housing cost, so a land-value effect bears directly on the belief.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (548, 103, 'argument', 'disagree', 1, 'The belief is about the overall level of housing costs; a rise in land value under existing homes can coexist with lower rents for new tenants.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (549, 103, 'argument', 'disagree', 2, 'Displacement and asset effects belong in the cost-benefit table as costs, not in the tree about whether housing costs fall.', 'Wrong parent');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (550, 104, 'argument', 'agree', 1, 'If the rent declines have another sufficient cause, the reform cities stop being evidence for the belief.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (551, 104, 'argument', 'disagree', 1, 'Cheap money explains the timing of the building, not why building happened in the reform cities and not elsewhere; the two causes are not exclusive.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (552, 105, 'argument', 'agree', 1, 'A permit surge confined to the upzoned areas is the supply response the belief predicts, measured against non-upzoned controls.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (553, 105, 'argument', 'disagree', 1, 'Consents measure permission to build, not rents; the finding bears on the mechanism, not on the cost outcome.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (554, 106, 'argument', 'agree', 1, 'Slower rent growth in a reform city against its own state is the belief''s outcome measured in the belief''s units.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (555, 106, 'argument', 'agree', 2, 'The finding pairs the rent divergence with a faster-growing housing stock, which is the mechanism the belief names.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (556, 106, 'argument', 'disagree', 1, 'Minneapolis changed several rules at once, so the finding bears on the package, not on the single-family change alone.', 'Wrong parent');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (557, 107, 'argument', 'agree', 1, 'A rent decline following a permitting boom is the belief''s causal chain observed end to end.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (558, 107, 'argument', 'disagree', 1, 'Austin''s apartments were built on commercial land, so the finding bears on permitting in general more than on single-family zoning.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (559, 108, 'argument', 'agree', 1, 'Rents falling near new buildings is the channel through which new supply reaches existing tenants.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (560, 108, 'argument', 'agree', 2, 'The effect appears in three cities with different densities and grows with the number of new units, so more supply means lower nearby rents across the range studied.', 'Monotonicity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (561, 108, 'argument', 'disagree', 1, 'Effects within a few hundred meters do not establish a citywide effect without a count of how many buildings a reform produces.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (562, 109, 'argument', 'agree', 1, 'A reform that produces a few hundred homes in a state of 39 million cannot have lowered costs through supply.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (563, 109, 'argument', 'disagree', 1, 'SB 9 was hedged with owner-occupancy and design rules; its count bears on that design, not on the belief as stated.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (564, 110, 'argument', 'agree', 1, 'Prices rising after upzoning with no new construction is the belief''s outcome reversed.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (565, 110, 'argument', 'disagree', 1, 'Narrow corridor upzonings are not the citywide change the belief names; the finding bears on a different policy.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (566, 110, 'argument', 'disagree', 2, 'Prices rising in upzoned parcels is option value being priced in; it bears on the belief only if construction never follows, which five years cannot show.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (567, 111, 'argument', 'agree', 1, 'Slower rent growth across many reform cities against matched controls is the belief''s own claim observed at scale.', 'Scope fit');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (568, 111, 'argument', 'agree', 2, 'If the belief is true there is no realistic way for many reform cities to show the same rent growth as their controls for a decade.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (569, 111, 'argument', 'disagree', 1, 'Matched controls can still differ in demand, so the observation would strengthen the belief less than a controlled comparison would.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (570, 112, 'argument', 'agree', 1, 'A reform city growing rents more slowly than its state is what the belief predicts.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (571, 112, 'argument', 'disagree', 1, 'One city''s divergence has several candidate causes, so the observation bears on the belief only through the attribution.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (572, 113, 'argument', 'agree', 1, 'Thousands of homes from lot splits would show the mechanism working in the hardest market.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (573, 113, 'argument', 'disagree', 1, 'Homes added are not costs lowered; the observation bears on supply, one step short of the belief.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (574, 114, 'argument', 'agree', 1, 'A growing effect over time across cities is the signature of a supply effect rather than a coincidence.', 'Monotonicity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (575, 114, 'argument', 'disagree', 1, 'Study design decides how much such a result shows; the prediction is only as diagnostic as its controls.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (576, 115, 'argument', 'agree', 1, 'A shrinking regulatory premium is the direct measure of zoning''s price effect being removed.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (577, 115, 'argument', 'disagree', 1, 'The premium can shrink because construction costs rose rather than because prices fell, so the observation is ambiguous.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (578, 116, 'argument', 'agree', 1, 'If reform cities are indistinguishable from others after controls, the reform did nothing the controls did not.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (579, 116, 'argument', 'disagree', 1, 'Over-controlling for permits or migration would absorb the reform''s own effect, so the observation depends on which controls are used.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (580, 117, 'argument', 'agree', 1, 'If the boom explains the whole rent effect, nothing is left for zoning to explain.', 'Necessity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (581, 117, 'argument', 'disagree', 1, 'The boom''s building happened in the cities that allowed it, so controlling for the boom can control away the reform.', 'Missing step');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (582, 118, 'argument', 'agree', 1, 'Lots rebuilt as one bigger house add no homes, so the supply mechanism would have failed where it was allowed.', 'Mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (583, 118, 'argument', 'disagree', 1, 'Larger single homes on some lots do not preclude multiplexes on others; the observation bears on the share, not on the belief.', 'Scope mismatch');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (584, 119, 'argument', 'agree', 1, 'Rent burdens are the reason most supporters give and the reason they turn out: renter-heavy districts vote for reform.', 'Predicts who holds the position');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (585, 119, 'argument', 'agree', 2, 'Affordability is the first reason supporters give at hearings and in polling.', 'Named first by holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (586, 119, 'argument', 'disagree', 1, 'Some support comes from builders and landowners whose interest is in land value, not affordability.', 'Tracks a different variable');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (587, 120, 'argument', 'agree', 1, 'Trade groups fund a share of pro-housing campaigns and lobby for the same bills.', 'Money and turnout follow it');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (588, 120, 'argument', 'disagree', 1, 'Most of the pro-housing coalition holds no development stake; builders are a minority of the movement''s voice.', 'Minority of holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (589, 121, 'argument', 'agree', 1, 'Support is strongest among younger residents and recent arrivals who have not found a place to live.', 'Predicts who holds the position');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (590, 121, 'argument', 'disagree', 1, 'Newcomers by definition do not yet vote in the city, so they are a small share of the coalition that shows up.', 'Minority of holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (591, 122, 'argument', 'agree', 1, 'Climate and transit groups name emissions first when they endorse reform bills.', 'Named first by holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (592, 122, 'argument', 'disagree', 1, 'Few residents testify for density because of regional emissions; the reason is stated by organizations more than by people.', 'Decorative');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (593, 123, 'argument', 'agree', 1, 'Opposition intensity tracks homeownership rates and home values more closely than any stated concern.', 'Predicts who holds the position');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (594, 123, 'argument', 'agree', 2, 'Opposition is strongest where home values are highest.', 'Tracks intensity');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (595, 123, 'argument', 'disagree', 1, 'Long-time renters oppose reform too, out of attachment to the neighborhood rather than equity.', 'Minority of holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (596, 124, 'argument', 'agree', 1, 'In older, lower-income neighborhoods, displacement is the concern residents name first at hearings.', 'Named first by holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (597, 124, 'argument', 'disagree', 1, 'The loudest opposition comes from high-value neighborhoods where displacement risk is lowest, so the fear drives a minority of the opposition.', 'Tracks a different variable');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (598, 125, 'argument', 'agree', 1, 'Parking and school crowding are the concerns opponents name first at hearings.', 'Named first by holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (599, 125, 'argument', 'disagree', 1, 'The same residents oppose projects that add no parking demand, which suggests the stated concern follows the position.', 'After-the-fact rationalization');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (600, 126, 'argument', 'agree', 1, 'Opposition tracks the income gap between current residents and likely new ones more closely than any stated concern.', 'Predicts who holds the position');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (601, 126, 'argument', 'disagree', 1, 'Most opponents name costs they experience, and many oppose market-rate housing that would bring higher-income neighbors.', 'Minority of holders');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (602, 127, 'argument', 'agree', 1, 'Both claims say that fewer rules on what may be built lower housing costs.', 'Interchangeable in arguments');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (603, 127, 'argument', 'disagree', 1, 'Abolishing zoning removes use separation and lot rules that the belief leaves in place; it is a different policy with different costs.', 'Different scope');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (604, 127, 'argument', 'disagree', 2, 'Abolition changes what uses are allowed anywhere; the belief changes only how many homes a residential lot may hold.', 'Different mechanism');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (605, 128, 'argument', 'agree', 1, 'Both say the reform slows rent growth where demand is high; the moderate version restates the belief with its scope made explicit.', 'Same truth conditions');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (606, 128, 'argument', 'agree', 2, 'The same reform-city rent data would confirm or refute both claims.', 'Same evidence settles both');
INSERT INTO edge (id, page_id, section, side, position, text, pattern) VALUES (607, 128, 'argument', 'disagree', 1, 'The belief claims lower costs in the cities that reform, without the modest qualifier or the high-demand restriction; the moderate version is a narrower claim.', 'Different magnitude');
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (608, 129, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (609, 129, 'interest_listing', 2, 73);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (610, 130, 'interest_listing', 1, 24);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (611, 131, 'interest_listing', 1, 25);
INSERT INTO edge (id, page_id, section, position, claim_id) VALUES (612, 131, 'interest_listing', 2, 73);
